mapper.select:
SELECT * FROM ( SELECT B.BOARD_NO, B.TITLE AS BOARD_TITLE, B.VIEW_COUNT AS READ_COUNT, B.STATUS AS BOARD_DEL_FL, TO_CHAR(B.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, M.NICKNAME AS MEMBER_NICKNAME, ROW_NUMBER() OVER (ORDER BY B.BOARD_NO DESC) AS RN FROM BOARD B JOIN MEMBER M ON B.MEMBER_NO = M.MEMBER_NO WHERE B.BOARD_CODE = 'NOTICE' AND B.STATUS = 'A'
AND B.TITLE LIKE '%' || #{search} || '%'
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE BOARD
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE BOARD_NO = #{boardNo}

